157	/// Reject one option unless it is entirely absent.
158	fn reject_non_default<T>(
159	    value: Option<&T>,
160	    param: &'static str,
161	    message: &str,
162	) -> Result<(), ApiError> {
163	    if value.is_some() {
164	        bail_invalid_request!(param = param, "{}", message);
165	    }
166	    Ok(())
167	}
