169	fn validate_function_tools(tools: &[Tool], param: &'static str) -> Result<(), ApiError> {
170	    for tool in tools {
171	        if tool.tool_type != "function" {
172	            bail_invalid_request!(param = param, "Only function tools are supported.");
173	        }
174	    }
175	    Ok(())
176	}
